shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #284159;
    --gold-ink: #e5b97f;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Language Switching Protocol */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.75;
  }

  /* Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line);
    padding: 0.75rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.1rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    padding: 0.15rem 0.5rem;
    background: var(--accent-soft);
    border-radius: 2px;
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.35rem 0.75rem;
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1120px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 2px solid var(--ink);
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 1.25rem;
  }

  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 28px;
    height: 2px;
    background: var(--accent);
  }

  .hero-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.5rem;
    max-width: 960px;
  }

  :host([lang="en"]) .hero-title {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.12;
  }

  .hero-subtitle {
    font-size: 1.15rem;
    line-height: 1.65;
    color: var(--muted);
    max-width: 780px;
    margin-bottom: 2rem;
    font-family: var(--font-serif-cn);
  }

  :host([lang="en"]) .hero-subtitle {
    font-family: var(--font-body-en);
    font-style: italic;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1.25rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-name {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.03em;
  }

  .dateline-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
  }

  .dateline-pill {
    background: var(--paper-card);
    border: 1px solid var(--line);
    padding: 0.25rem 0.65rem;
    border-radius: 2px;
    color: var(--body);
  }

  /* Main Container & Editorial Grid */
  .editorial-container {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  .chapter-section {
    margin-bottom: 3.5rem;
  }

  .chapter-banner {
    display: flex;
    align-items: baseline;
    gap: 1rem;
    margin-bottom: 2rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--line-strong);
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .chapter-title {
    font-family: var(--font-sans);
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.02em;
  }

  .asymmetric-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.85fr) minmax(280px, 1fr);
    gap: 3rem;
    align-items: start;
  }

  /* Prose Styling */
  .prose-col {
    min-width: 0;
  }

  .prose-p {
    font-size: 1.125rem;
    line-height: 1.9;
    color: var(--body);
    margin-bottom: 1.45rem;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    line-height: 1.8;
  }

  .prose-p.lead-para {
    font-size: 1.24rem;
    line-height: 1.85;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
  }

  :host([lang="en"]) .prose-p.lead-para {
    font-weight: 400;
    font-size: 1.22rem;
  }

  /* Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.16) 0%, rgba(184, 93, 25, 0.24) 100%);
    color: var(--ink);
    padding: 0.08em 0.28em;
    border-radius: 2px;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
    font-weight: inherit;
  }

  /* Side Rail Dossiers & Callouts */
  .side-rail {
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    min-width: 0;
  }

  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.35rem;
    border-radius: 2px;
  }

  .dossier-header {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.75rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .dossier-title {
    font-family: var(--font-sans);
    font-size: 1rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.85rem;
    line-height: 1.4;
  }

  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
    font-family: var(--font-sans);
    font-size: 0.85rem;
    line-height: 1.55;
    color: var(--body);
  }

  .dossier-list li {
    padding-top: 0.65rem;
    border-top: 1px dashed var(--line-strong);
  }

  .dossier-list li:first-child {
    padding-top: 0;
    border-top: none;
  }

  .dossier-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
    display: block;
    margin-bottom: 0.15rem;
    text-transform: uppercase;
  }

  /* Derived Pull Quotes & Metric Cards */
  .pull-quote {
    background: var(--paper-card);
    border-left: 3px solid var(--accent);
    padding: 1.25rem 1.35rem;
    margin: 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.05rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.65rem;
  }

  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--font-serif-en);
    font-style: italic;
    font-weight: 700;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .metric-card {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.4rem;
    border-radius: 2px;
    border-top: 3px solid var(--accent);
  }

  .metric-card .metric-val {
    font-family: var(--font-mono);
    font-size: 2.35rem;
    font-weight: 700;
    color: var(--gold-ink);
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }

  .metric-card .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 0.4rem;
  }

  .metric-card .metric-note {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    line-height: 1.5;
    color: #b0beca;
  }

  /* Interactive / Bespoke SVG Diagrams */
  .figure-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.75rem;
    margin: 2.25rem 0;
    border-radius: 2px;
  }

  .figure-kicker {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.35rem;
  }

  .figure-title {
    font-family: var(--font-sans);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.4rem;
  }

  .figure-desc {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    color: var(--muted);
    margin-bottom: 1.25rem;
    line-height: 1.55;
  }

  .figure-caption {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
    margin-top: 1rem;
    padding-top: 0.75rem;
    border-top: 1px solid var(--line);
  }

  /* Split Sentence Callout Block inside Primary Flow */
  .inline-verdict-box {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.65rem 1.85rem;
    margin: 1.65rem 0;
    border-left: 4px solid var(--accent);
    border-radius: 2px;
  }

  .inline-verdict-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--gold-ink);
    margin-bottom: 0.5rem;
    display: block;
  }

  .inline-verdict-quote {
    font-family: var(--font-serif-cn);
    font-size: 1.25rem;
    font-weight: 600;
    line-height: 1.6;
    color: #ffffff;
  }

  :host([lang="en"]) .inline-verdict-quote {
    font-family: var(--font-serif-en);
    font-style: italic;
  }

  /* Policy Comparison Matrix (Warsh vs Hammack) */
  .comparison-matrix {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.25rem;
    margin: 2rem 0;
  }

  .matrix-col {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
    border-radius: 2px;
  }

  .matrix-col.hammack-col {
    border-top: 3px solid var(--accent);
  }

  .matrix-col.warsh-col {
    border-top: 3px solid var(--navy-bg);
  }

  .matrix-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.3rem;
  }

  .matrix-head {
    font-family: var(--font-sans);
    font-size: 1.02rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }

  .matrix-body {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    line-height: 1.6;
    color: var(--body);
  }

  /* Footer */
  .ed-footer {
    border-top: 2px solid var(--ink);
    padding: 2.5rem 1.5rem 4rem;
    max-width: 1120px;
    margin: 0 auto;
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 860px) {
    .asymmetric-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .comparison-matrix {
      grid-template-columns: 1fr;
    }
    .hero {
      padding: 2.25rem 1.15rem 1.75rem;
    }
    .editorial-container {
      padding: 1.75rem 1.15rem 3.5rem;
    }
    .figure-panel {
      padding: 1.15rem;
    }
  }
